"""Flask API serving sentiment analysis with a local DistilBERT model."""
import logging
from flask import Flask, jsonify, request
from transformers import pipeline

MODEL_DIR = "/app/model_cache/sentiment_model"

app = Flask(__name__)
logging.basicConfig(level=logging.INFO)

_classifier = None

def get_classifier():
    """Lazily load the pipeline from the local model cache."""
    global _classifier
    if _classifier is None:
        _classifier = pipeline(
            "text-classification",
            model=MODEL_DIR,
            tokenizer=MODEL_DIR,
            top_k=None,  # return scores for all labels
        )
    return _classifier


@app.route("/sentiment", methods=["POST"])
def sentiment():
    data = request.get_json(silent=True)
    if data is None:
        return jsonify({"error": "Request body must be valid JSON."}), 400
    if not isinstance(data, dict):
        return jsonify({"error": "Request body must be a JSON object."}), 400
    if "text" not in data:
        return jsonify({"error": "Missing required field 'text'."}), 400
    text = data["text"]
    if not isinstance(text, str):
        return jsonify({"error": "Field 'text' must be a string."}), 400

    try:
        clf = get_classifier()
        results = clf(text)
        scores = {str(item["label"]).lower(): float(item["score"]) for item in results}
        positive = scores.get("positive", 0.0)
        negative = scores.get("negative", 0.0)
        label = "positive" if positive >= negative else "negative"
        return jsonify(
            {
                "sentiment": label,
                "confidence": {"positive": positive, "negative": negative},
            }
        )
    except Exception as exc:
        logging.exception("Sentiment analysis failed")
        return jsonify({"error": f"Sentiment analysis failed: {exc}"}), 500


@app.route("/health", methods=["GET"])
def health():
    return jsonify({"status": "ok"}), 200


if __name__ == "__main__":
    # Preload the model at startup so the first request is fast.
    get_classifier()
    app.run(host="0.0.0.0", port=5000)
