    except urllib.error.HTTPError as e:
        return e.code, json.loads(e.read())

tests = [
    ("positive text", {"text": "This movie was absolutely wonderful and I loved every minute of it!"}, 200, "positive"),
    ("negative text", {"text": "This is the worst product I have ever bought. Terrible quality, total waste of money."}, 200, "negative"),
    ("missing text", {"foo": "bar"}, 400, None),
    ("non-string text", {"text": 12345}, 400, None),
    ("non-dict body", ["hello"], 400, None),
    ("malformed json", "not json at all", 400, None),
]
ok = True
for name, payload, want_status, want_sent in tests:
    status, resp = post(payload, raw=isinstance(payload, str))
    got_sent = resp.get("sentiment")
    conf = resp.get("confidence", {})
    line = f"--- {name}: HTTP {status} -> {json.dumps(resp)}"
    print(line)
    if status != want_status: ok = False; print("   !! expected status", want_status)
    if want_sent and got_sent != want_sent: ok = False; print("   !! expected sentiment", want_sent)
